"""Generate bundled, explicitly synthetic examples and faithful document content."""
import json, pathlib, shutil, math
R=pathlib.Path(__file__).resolve().parents[1]
assets=[('gold','Gold','Edelmetalle','EUR/Feinunze'),('silver','Silber','Edelmetalle','EUR/Feinunze'),('dax','DAX','Aktien','Indexpunkte'),('dow','Dow Jones','Aktien','Indexpunkte'),('lseg','LSEG.L','Aktien','GBp/Aktie'),('berlin','Berlin','Immobilien','EUR/m²'),('mallorca','Mallorca','Immobilien','EUR/m²'),('paris','Paris','Immobilien','EUR/m²'),('london','London','Immobilien','GBP/m²'),('newyork','New York','Immobilien','USD/m²')]
sources=[('gold.de','Gold, Silber, Gold-Silber-Ratio','https://www.gold.de/kurse/goldpreis/'),('gold.de','Silberpreis','https://www.gold.de/kurse/silberpreis/'),('gold.de','Gold-Silber-Ratio','https://www.gold.de/kurse/gold-silber-ratio/'),('Yahoo Finance','DAX','https://de.finance.yahoo.com/quote/%5EGDAXI/'),('Yahoo Finance','Dow Jones','https://de.finance.yahoo.com/quote/%5EDJI/'),('Yahoo Finance','LSEG.L (Einzelaktie, kein Londoner Marktindex)','https://finance.yahoo.com/quote/LSEG.L/'),('Engel & Völkers','Berlin','https://www.engelvoelkers.com/de-de/immobilienpreise/berlin/'),('Engel & Völkers','Mallorca / Palma','https://www.engelvoelkers.com/es/de/immobilienpreise/balearische-inseln/palma-de-mallorca'),('Properstar','Paris','https://www.properstar.de/frankreich/paris/immobilienpreise'),('Properstar','London','https://www.properstar.de/vereinigtes-konigreich/london/immobilienpreise'),('Properstar','New York','https://www.properstar.de/usa/new-york/immobilienpreise')]
# Reconstruct URLs split by PDF line wrapping, retaining semantic word separators.
statista=[('1046','inflationsrate-veraenderung-des-verbraucherpreisindexes-zum-vorjahr'),('169933','inflationsrate-in-spanien'),('165718','inflationsrate-in-den-usa'),('167248','inflationsrate-in-frankreich'),('167319','inflationsrate-in-grossbritannien'),('183059','militaerausgaben-der-usa'),('183064','militaerausgaben-von-deutschland'),('362568','entwicklung-der-militaerausgaben-von-spanien'),('322721','entwicklung-der-militaerausgaben-von-frankreich'),('1251','entwicklung-des-bruttoinlandsprodukts-seit-dem-jahr-1991'),('19358','bruttoinlandsprodukt-in-spanien'),('14396','bruttoinlandsprodukt-in-frankreich'),('14418','bruttoinlandsprodukt-in-den-usa'),('14417','bruttoinlandsprodukt-in-grossbritannien')]
for id,slug in statista:sources.append(('Statista','Makrolage (Lizenz/Zugang erforderlich)',f'https://de.statista.com/statistik/daten/studie/{id}/umfrage/{slug}/'))
docs=[]
for p in sorted((R/'docs/source-text').glob('*.txt')):
 pages=['\n'.join(l.strip() for l in page.splitlines() if l.strip()) for page in p.read_text().split('\f')]
 pdf=next((R/'web/assets').glob(p.stem+'.pdf'))
 docs.append({'id':p.stem,'title':{'Farbcode RGB':'Farbcode RGB','crisis_brandguide':'Brandguide','crisis_daten_api':'Daten & Quellen','crisis_goldverbote_whitepaper':'Goldverbote & Geldordnung','crisis_wirkungsjahr2026-geopolitische_und_marktstrategische_feldanalyse':'Wirkungsjahr 2026','crisis©_formel_definition':'Formeldefinition'}[p.stem],'file':pdf.name,'pages':[x for x in pages if x.strip()]})
content={'schemaVersion':1,'brand':{'name':'CRISIS ©','tagline':'Wissen, das Werte schützt.','navy':'#0f1c3d','rose':'#e8b9c8','teal':'#c7e8e3'},'notice':'Orientierung, keine Anlageberatung. Historische Muster und Modelljahre sind keine belastbaren Prognosen.','cycles':[{'id':'events','name':'Große Ereignisse','start':1911,'steps':[16,18,20]},{'id':'high','name':'Hohe Preise','start':1918,'steps':[8,9,10]},{'id':'low','name':'Niedrige Preise','start':1924,'steps':[7,11,9]}],'sources':[{'provider':a,'label':b,'url':c} for a,b,c in sources],'documents':docs,'fields':[{'title':'Macht & Konflikt','text':'Dauerhafte Spannungen, fragmentierte Kooperation und Zugang zu Ressourcen. Ein Deutungsrahmen des Dossiers, kein gemessener Risikoindex.'},{'title':'Markt & Währung','text':'Liquidität, Verfügbarkeit und regulatorische Bedingungen ergänzen den Blick auf Rendite.'},{'title':'Technologie & Infrastruktur','text':'Abhängigkeiten von Plattformen, Daten und kritischen Netzen beeinflussen Handlungsfähigkeit.'},{'title':'Gesellschaft & Anpassung','text':'Operative Stabilität, Vertrauen und Versorgung prägen die im Dossier beschriebenen Wirkungsräume.'}]}
series=[]
for i,(id,name,group,unit) in enumerate(assets):
 points=[{'year':y,'value':round((20+i*83)*math.exp((y-1926)*(0.018+i*.001))*(1+.12*math.sin((y-1926)/5+i)),4)} for y in range(1926,2027)]
 series.append({'id':id,'name':name,'group':group,'unit':unit,'currency':('GBP' if id in ['lseg','london'] else 'USD' if id in ['dow','newyork'] else 'EUR'),'points':points})
data={'schemaVersion':1,'kind':'demo','asOf':'2026-01-01','source':'Synthetische Beispieldaten – keine historischen Marktwerte','cpiRegion':'DE','cpi':[{'year':y,'value':round(100*1.025**(y-1926),6)} for y in range(1926,2027)],'series':series,'macro':[{'country':c,'inflation':None,'military':None,'gdp':None} for c in ['Deutschland','Spanien','USA','Frankreich','Großbritannien']]}
for name,obj in [('content',content),('demo-data',data)]:
 (R/'shared'/f'{name}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
for d in [R/'web/assets',R/'android/app/src/main/assets',R/'ios/CRISIS/Resources']:
 for f in ['content.json','demo-data.json','planning.json']:shutil.copy(R/'shared'/f,d/f)
for d in [R/'android/app/src/main/assets',R/'ios/CRISIS/Resources']:shutil.copy(R/'web/assets/logo.png',d/'logo.png')
